cat > /tmp/verify/debug_ui.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    page.on('console', m => { if (m.type() === 'debug' || m.type() === 'log' || m.type() === 'warning' || m.type() === 'error') console.log('[' + m.type() + '] ' + m.text()); });
    page.on('pageerror', e => console.log('[pageerror] ' + e.message));
    await page.goto('http://localhost/index.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(4000);
    await page.selectOption('#chooseIndex', { label: 'spotify_tracks' });
    await page.waitForTimeout(5000);
    await page.click('.oneCollapsibleItem.filter .collapsible-header');
    await page.waitForTimeout(1000);
    await page.selectOption('#dataExplorerDataFields', { index: 1 });
    await page.waitForTimeout(2000);
    const filterDest = await page.$eval('#filterDestination', el => el.innerHTML).catch(e => 'ERR ' + e.message);
    console.log('FILTER_DESTINATION_HTML: ' + filterDest.slice(0, 1500));
    const outputHtml = await page.$eval('#outputControls', el => el.innerHTML).catch(e => 'ERR ' + e.message);
    console.log('OUTPUT_CONTROLS_HTML: ' + outputHtml.slice(0, 800));
    // list all selects on page
    const selects = await page.$$eval('select', els => els.map(s => ({ id: s.id, opts: Array.from(s.options).map(o => o.textContent.trim()), visible: s.offsetParent !== null })));
    console.log('SELECTS: ' + JSON.stringify(selects, null, 1));
    await browser.close();
})().catch(e => { console.error('DBG_FAILED', e); process.exit(1); });
EOF
cd /tmp/verify && node debug_ui.js 2>&1 | head -80
